1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Deliberately additive: `policyBase * 1.1` is not float-equivalent
51	// (100 * 1.1 === 110.00000000000001), and the final rounding-up turns that
52	// stray ulp into a whole extra gold piece. Do not "simplify".
53	const withFirstInsuranceSurcharge = (policyBase: number): number =>
54	  policyBase + policyBase * FIRST_INSURANCE_RATE;
55	
56	// The MHPCO rounds premiums in its own favour.
57	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
58	
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
62	
63	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
64	
65	// A group is every item of one single type, so a group is always non-empty
66	// and homogeneous — the block rule below relies on both.
67	interface TypeGroup {
68	  type: string;
69	  items: Item[];
70	}
71	
72	const groupByType = (items: Item[]): TypeGroup[] =>
73	  [
74	    ...items.reduce(
75	      (groups, item) =>
76	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
77	      new Map<string, Item[]>(),
78	    ),
79	  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));
80	
81	const formsComponentBlock = (group: TypeGroup): boolean =>
82	  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);
83	
84	const sumOfItemBasePremiums = (items: Item[]): number =>
85	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
86	
87	const groupBasePremium = (group: TypeGroup): number =>
88	  formsComponentBlock(group)
89	    ? COMPONENT_BLOCK_PREMIUM
90	    : sumOfItemBasePremiums(group.items);
91	
92	const policyBasePremium = (items: Item[]): number =>
93	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
94	
95	const CURSE_SURCHARGE_RATE = 0.5;
96	
97	// Item-specific modifiers are charged on the affected item's own base premium,
98	// unlike the policy-wide modifiers which apply to the sum of all of them.
99	const curseSurcharge = (item: Item): number =>
100	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
101	
102	const HIGH_ENCHANTMENT_LEVEL = 5;
103	const HIGH_ENCHANTMENT_RATE = 0.3;
104	
105	const highEnchantmentSurcharge = (item: Item): number =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
107	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE
108	    : 0;
109	
110	const itemSurcharge = (item: Item): number =>
111	  curseSurcharge(item) + highEnchantmentSurcharge(item);
112	
113	const totalItemSurcharges = (items: Item[]): number =>
114	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
115	
116	const quotePremium = (items: Item[]): number =>
117	  roundedInMHPCOsFavour(
118	    withFirstInsuranceSurcharge(policyBasePremium(items)) +
119	      totalItemSurcharges(items) +
120	      PROCESSING_FEE,
121	  );
122	
123	const runStep = (step: Step): StepResult => {
124	  if (step.op === "quote") return { premium: quotePremium(step.items) };
125	  throw new Error(`unsupported step: ${step.op}`);
126	};
127	
128	export const runScenario = (scenario: Scenario): ScenarioResult => ({
129	  results: scenario.steps.map(runStep),
130	});
