const HIGH_ENCHANTMENT_LEVEL = 5;

// Item-specific modifiers are charged on the affected item's own base premium,
// unlike the policy-wide modifiers which apply to the sum of all of them.
interface ItemSurchargeRule {
  appliesTo: (item: Item) => boolean;
  rate: number;
}

const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
    rate: 0.3,
  },
];

const itemSurcharge = (item: Item): number =>
  ITEM_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
    (sum, rule) => sum + basePremiumOf(item) * rule.rate,
    0,
  );

