const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_RATE = 0.3;

// An unenchanted item may leave `enchantment` unset; absent means level 0.
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const highEnchantmentSurcharge = (item: Item): number =>
  isHighlyEnchanted(item) ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE : 0;
